import java.util.Scanner;
import java.util.Arrays;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // 读入矿工数 $n$ 和矿点数 $m$
        int n = sc.nextInt();
        int m = sc.nextInt();
        // 定义矿工挖掘高度数组 $a$ 和矿点高度数组 $b$
        long[] a = new long[n];
        long[] b = new long[m];
        long[] cur = new long[m]; // 用于记录每个矿点已挖走的高度，初始均为 0
        for (int i = 0; i < n; i++){
            a[i] = sc.nextLong();
        }
        for (int j = 0; j < m; j++){
            b[j] = sc.nextLong();
        }
        // 模拟每个矿工的挖矿过程
        for (int i = 0; i < n; i++){
            long total = 0; // 累计当前矿工挖到的矿物数量
            for (int j = 0; j < m; j++){
                // 如果该矿点还有矿，并且当前矿工的挖掘高度大于已挖高度
                if (cur[j] < b[j] && a[i] > cur[j]){
                    // 计算当前矿工可以挖走的矿物数量
                    long remove = Math.min(a[i], b[j]) - cur[j];
                    total += remove;
                    cur[j] += remove; // 更新该矿点已挖走的高度
                }
            }
            // 输出当前矿工挖到的矿物数量
            System.out.print(total + (i < n - 1 ? " " : "\n"));
        }
        sc.close();
    }
}
